3	// Regression coverage for calendar validity in timestamp normalization.
4	//
5	// A timestamp's date must really exist in the year/month/day as written,
6	// before any timezone conversion is applied: 2000 is a leap year, 1900 is
7	// not, ordinary common years have no February 29, and a 30-day month has
8	// no 31st (the day must never roll over into the next month). Only once
9	// the written date is accepted is the instant converted to UTC, where a
10	// conversion may legitimately move it across midnight — including onto a
11	// leap day or off the end of a month — without dropping the event.
12	//
13	// These tests go through the same public NormalizeReader/NormalizeLine
14	// output as every other caller and introduce no new timestamp shapes.
15	
16	import (
17		"bytes"
18		"encoding/json"
19		"errors"
20		"io"
21		"strings"
22		"testing"
23	)
24	
25	// calendarLine wraps one RFC3339 value in a log object carrying the
26	// timestamp under either its canonical name or its alias, plus an action
27	// so the success path has an event to preserve across midnight.
28	func calendarLine(key, ts, action string) string {
29		return `{"` + key + `":"` + ts + `","action":"` + action + `"}`
30	}
31	
32	// bothTimestampKeys runs one check with the value under "timestamp" and
33	// under "time"; both spellings must behave identically.
34	func bothTimestampKeys(ts, action string) []string {
35		return []string{
36			calendarLine(FieldTimestamp, ts, action),
37			calendarLine("time", ts, action),
38		}
39	}
40	
41	// TestNormalizeCalendarExistingDatesAccepted pins real month-end and leap
42	// dates, including the centuries and 31/30-day month boundaries that tell
43	// a real calendar check apart from a day<=31 shortcut.
44	func TestNormalizeCalendarExistingDatesAccepted(t *testing.T) {
45		ok := map[string]string{
46			"2000-02-29T00:00:00Z":      "2000-02-29T00:00:00Z", // divisible by 400: leap
47			"2000-02-29T23:59:59.5Z":    "2000-02-29T23:59:59.5Z",
48			"2024-02-29T12:00:00Z":      "2024-02-29T12:00:00Z", // ordinary leap year
49			"1900-02-28T12:00:00Z":      "1900-02-28T12:00:00Z", // 1900 is common; the 28th is its last February day
50			"2000-02-28T12:00:00Z":      "2000-02-28T12:00:00Z",
51			"2000-04-30T12:00:00Z":      "2000-04-30T12:00:00Z", // last day of a 30-day month
52			"2000-06-30T23:59:59Z":      "2000-06-30T23:59:59Z",
53			"2000-11-30T00:00:00Z":      "2000-11-30T00:00:00Z",
54			"2000-01-31T12:00:00Z":      "2000-01-31T12:00:00Z", // last day of a 31-day month
55			"2000-12-31T23:59:59Z":      "2000-12-31T23:59:59Z",
56			"2001-03-01T00:00:00Z":      "2001-03-01T00:00:00Z", // day after common-year Feb 28 exists
57			"2000-02-29T00:00:00+01:00": "2000-02-28T23:00:00Z", // leap day accepted before conversion
58		}
59		for in, want := range ok {
60			for _, wrapper := range bothTimestampKeys(in, "a") {
61				results := runNormalize(t, wrapper)
62				if results[0]["ok"] != true {
63					t.Fatalf("real calendar date %q must be accepted, got %#v", in, results[0])
64				}
65				if got := eventOf(t, results[0])[FieldTimestamp]; got != want {
66					t.Fatalf("date %q -> %v, want %q", in, got, want)
67				}
68			}
69		}
70	}
71	
72	// TestNormalizeCalendarNonexistentDatesRejected pins the core rule: the
73	// written year/month/day combination must exist. Failures name the
74	// timestamp field, carry a date ("day out of range") complaint, and emit
75	// no event — a 31st in a 30-day month must never be carried to day 1.
76	func TestNormalizeCalendarNonexistentDatesRejected(t *testing.T) {
77		bad := []string{
78			"1900-02-29T00:00:00Z", // century not divisible by 400: not a leap year
79			"2001-02-29T12:00:00Z", // ordinary common year
80			"1999-02-29T23:59:59Z",
81			"2000-02-30T00:00:00Z", // leap February still ends on the 29th
82			"2024-02-30T00:00:00Z",
83			"2000-04-31T00:00:00Z", // must not become 2000-05-01
84			"2001-04-31T12:00:00Z",
85			"2000-06-31T00:00:00Z",
86			"2000-09-31T00:00:00Z",
87			"2000-11-31T00:00:00Z",
88			// The written local fields are judged first: even though the zone
89			// conversion would land both on a real February 28/March 1 date,
90			// the date as spelled does not exist and must fail.
91			"2001-02-29T00:30:00+01:00", // converts to 2001-02-28T23:30Z
92			"1900-02-29T23:30:00-01:00", // converts to 1900-03-01T00:30Z
93		}
94		for _, in := range bad {
95			for _, wrapper := range bothTimestampKeys(in, "a") {
96				results := runNormalize(t, wrapper)
97				if results[0]["ok"] != false {
98					t.Fatalf("nonexistent date %q must fail, got %#v", in, results[0])
99				}
100				if _, exists := results[0]["event"]; exists {
101					t.Fatalf("nonexistent date %q must not roll over into an event: %#v", in, results[0])
102				}
103				msg, _ := results[0]["error"].(string)
104				if !strings.Contains(msg, FieldTimestamp) {
105					t.Fatalf("error for %q must name %q, got %q", in, FieldTimestamp, msg)
106				}
107				if !strings.Contains(msg, "day out of range") {
108					t.Fatalf("error for %q must report the calendar-date problem, got %q", in, msg)
109				}
110			}
111		}
112	}
113	
114	// TestNormalizeCalendarCrossMidnightConversionOutput checks legal dates
115	// whose zone conversion crosses midnight: the moved date (including onto a
116	// leap day and off a month end) is visible directly in the canonical
117	// timestamp, and the action survives instead of the event being lost.
118	func TestNormalizeCalendarCrossMidnightConversionOutput(t *testing.T) {
119		cases := []struct {
120			name string
121			in   string
122			want string
123		}{
124			{"leap day minus offset rolls back to Feb 28", "2000-02-29T00:30:00+01:00", "2000-02-28T23:30:00Z"},
125			{"Feb 28 minus offset rolls onto the leap day", "2000-02-28T23:30:00-01:00", "2000-02-29T00:30:00Z"},
126			{"leap day evening rolls into March", "2000-02-29T23:30:00-01:00", "2000-03-01T00:30:00Z"},
127			{"March 1 early rolls back onto the leap day", "2000-03-01T00:30:00+01:00", "2000-02-29T23:30:00Z"},
128			{"common-year Feb 28 rolls onto March 1", "2001-02-28T23:30:00-01:00", "2001-03-01T00:30:00Z"},
129			{"April 30 evening rolls onto May 1", "2000-04-30T23:30:00-01:00", "2000-05-01T00:30:00Z"},
130			{"May 1 early rolls back to April 30", "2000-05-01T00:30:00+01:00", "2000-04-30T23:30:00Z"},
131		}
132		for _, tc := range cases {
133			t.Run(tc.name, func(t *testing.T) {
134				for _, wrapper := range bothTimestampKeys(tc.in, "login") {
135					results := runNormalize(t, wrapper)
136					if results[0]["ok"] != true {
137						t.Fatalf("legal date crossing midnight must succeed, got %#v", results[0])
138					}
139					event := eventOf(t, results[0])
140					if got := event[FieldTimestamp]; got != tc.want {
141						t.Fatalf("%q -> %v, want %q", tc.in, got, tc.want)
142					}
143					// Crossing a date boundary must not drop the record or
144					// disturb the independently normalized action.
145					if event[FieldAction] != "login" {
146						t.Fatalf("action lost across midnight: %#v", event)
147					}
148				}
149			})
150		}
151	}
152	
153	// TestNormalizeCalendarCanonicalAndAliasMergeAcrossDateBoundary: the
154	// canonical name and its alias may spell one instant with different
155	// written dates and different offsets (one side on each side of midnight).
156	// Both values validating and converting to the same UTC instant must merge
157	// into that one timestamp, in either key assignment.
158	func TestNormalizeCalendarCanonicalAndAliasMergeAcrossDateBoundary(t *testing.T) {
159		cases := []struct {
160			name      string
161			canonical string
162			alias     string
163			want      string
164		}{
165			{
166				name:      "leap day early and Feb 28 evening are one instant",
167				canonical: "2000-02-29T00:30:00+01:00", // -> 28th 23:30Z
168				alias:     "2000-02-28T18:30:00-05:00", // -> 28th 23:30Z
169				want:      "2000-02-28T23:30:00Z",
170			},
171			{
172				name:      "Feb 28 evening and leap day early morning are one instant",
173				canonical: "2000-02-28T23:30:00-01:00", // -> 29th 00:30Z
174				alias:     "2000-02-29T05:30:00+05:00", // -> 29th 00:30Z
175				want:      "2000-02-29T00:30:00Z",
176			},
177			{
178				name:      "leap day evening and March 1 early morning are one instant",
179				canonical: "2000-02-29T23:30:00-01:00", // -> Mar 1 00:30Z
180				alias:     "2000-03-01T01:30:00+01:00", // -> Mar 1 00:30Z
181				want:      "2000-03-01T00:30:00Z",
182			},
183		}
184		for _, tc := range cases {
185			t.Run(tc.name, func(t *testing.T) {
186				wrappers := []string{
187					`{"timestamp":"` + tc.canonical + `","time":"` + tc.alias + `","action":"a"}`,
188					`{"timestamp":"` + tc.alias + `","time":"` + tc.canonical + `","action":"a"}`,
189				}
190				for _, wrapper := range wrappers {
191					results := runNormalize(t, wrapper)
192					if results[0]["ok"] != true {
193						t.Fatalf("same instant spelled across a date boundary must merge, got %#v", results[0])
194					}
195					if got := eventOf(t, results[0])[FieldTimestamp]; got != tc.want {
196						t.Fatalf("merged timestamp %v, want %q", got, tc.want)
197					}
198				}
199			})
200		}
201	}
202	
203	// TestNormalizeCalendarInvalidDateFailsWholeLine: when canonical name and
204	// alias coexist, every written date must be valid on its own. A nonexistent
205	// date on one side fails the entire line even when the other side is legal,
206	// and even when a lenient "roll the date over, then compare" parser would
207	// find the two equal. The error is always attributed to "timestamp",
208	// regardless of which key carried the bad value, and is an invalid-value
209	// error rather than a value conflict.
210	func TestNormalizeCalendarInvalidDateFailsWholeLine(t *testing.T) {
211		cases := []struct {
212			name  string
213			input string
214		}{
215			{
216				name:  "legal canonical, nonexistent alias",
217				input: `{"timestamp":"2000-02-28T00:00:00Z","time":"1900-02-29T00:00:00Z","action":"a"}`,
218			},
219			{
220				name:  "nonexistent canonical, legal alias",
221				input: `{"timestamp":"2001-02-29T00:00:00Z","time":"2000-02-28T00:00:00Z","action":"a"}`,
222			},
223			{
224				// A forgiving parser would roll Feb 29 (common year) forward to
225				// March 1, making 01:30+01:00 the same instant as the legal
226				// canonical value; validation must happen before that comparison.
227				name:  "legal canonical, alias invalid but rollover would match",
228				input: `{"timestamp":"2001-03-01T00:30:00Z","time":"2001-02-29T01:30:00+01:00","action":"a"}`,
229			},
230			{
231				name:  "same trap with the invalid date under the canonical name",
232				input: `{"timestamp":"2001-02-29T01:30:00+01:00","time":"2001-03-01T00:30:00Z","action":"a"}`,
233			},
234			{
235				name:  "alias only: bad date still attributed to canonical field",
236				input: `{"time":"2026-04-31T00:00:00Z","action":"a"}`,
237			},
238			{
239				name:  "canonical only: same failure",
240				input: `{"timestamp":"2026-04-31T00:00:00Z","action":"a"}`,
241			},
242		}
243		for _, tc := range cases {
244			t.Run(tc.name, func(t *testing.T) {
245				results := runNormalize(t, tc.input)
246				if results[0]["ok"] != false {
247					t.Fatalf("line with one nonexistent date must fail: %#v", results[0])
248				}
249				if _, exists := results[0]["event"]; exists {
250					t.Fatalf("invalid date must not emit a partial event: %#v", results[0])
251				}
252				msg, _ := results[0]["error"].(string)
253				if !strings.Contains(msg, FieldTimestamp) {
254					t.Fatalf("error must be attributed to %q even when only the alias is bad, got %q", FieldTimestamp, msg)
255				}
256				if !strings.Contains(msg, "day out of range") {
257					t.Fatalf("error must identify the calendar-date problem, got %q", msg)
258				}
259				if strings.Contains(msg, "conflicting values") {
260					t.Fatalf("an invalid date must be rejected as invalid, not compared: %q", msg)
261				}
262			})
263		}
264	}
265	
266	// TestNormalizeCalendarMixedStream interleaves legal leap days,
267	// nonexistent dates, and ordinary legal dates in one stream, with blank
268	// physical lines between them. Every non-blank line must produce exactly
269	// one result carrying its original physical line number; date errors count
270	// only against their own line, later legal records still come out in order,
271	// and a normal EOF reports the date failures as per-line failures rather
272	// than a stream read/write error.
273	func TestNormalizeCalendarMixedStream(t *testing.T) {
274		input := "{\"timestamp\":\"2000-02-29T12:00:00Z\",\"action\":\"a\"}\n" + // line 1: legal leap day
275			"\n" + // line 2: blank, only advances the counter
276			"{\"timestamp\":\"1900-02-29T12:00:00Z\",\"action\":\"b\"}\n" + // line 3: bad date
277			"{\"timestamp\":\"2026-04-15T12:00:00Z\",\"action\":\"c\"}\n" + // line 4: legal ordinary date
278			"  \t  \n" + // line 5: blank
279			"{\"time\":\"2026-04-31T12:00:00Z\",\"action\":\"d\"}\n" + // line 6: bad date under alias
280			"{\"timestamp\":\"2000-02-28T23:30:00-01:00\",\"action\":\"e\"}\n" + // line 7: legal, crosses onto leap day
281			"{\"timestamp\":\"2001-02-29T00:30:00+01:00\",\"action\":\"f\"}\n" + // line 8: bad written date despite UTC landing on Feb 28
282			"{\"timestamp\":\"2000-04-30T23:30:00-01:00\",\"action\":\"g\"}" // line 9: legal, no trailing newline (clean EOF)
283	
284		var out bytes.Buffer
285		failures, err := NormalizeReader(strings.NewReader(input), &out)
286		if err != nil {
287			t.Fatalf("normal EOF with bad-date lines must not be a stream failure: %v", err)
288		}
289		if errors.Is(err, ErrLogRead) || errors.Is(err, ErrLogWrite) {
290			t.Fatalf("invalid dates are per-line normalization failures, got stream error: %v", err)
291		}
292		if failures != 3 {
293			t.Fatalf("exactly the 3 nonexistent-date lines must count as failures, got %d", failures)
294		}
295	
296		results := []map[string]any{}
297		dec := json.NewDecoder(bytes.NewReader(out.Bytes()))
298		for {
299			var m map[string]any
300			if derr := dec.Decode(&m); derr != nil {
301				if errors.Is(derr, io.EOF) {
302					break
303				}
304				t.Fatalf("decoding result: %v", derr)
305			}
306			results = append(results, m)
307		}
308		if len(results) != 7 {
309			t.Fatalf("each of the 7 non-blank lines must yield exactly one result, got %d: %#v", len(results), results)
310		}
311		if got := countFailures(results); got != failures {
312			t.Fatalf("output shows %d failures but NormalizeReader returned %d", got, failures)
313		}
314	
315		wantLines := []int{1, 3, 4, 6, 7, 8, 9}
316		wantOK := []bool{true, false, true, false, true, false, true}
317		for i, r := range results {
318			if r["line"] != float64(wantLines[i]) {
319				t.Fatalf("result %d must keep physical line %d, got %v: %#v", i, wantLines[i], r["line"], r)
320			}
321			if r["ok"] != wantOK[i] {
322				t.Fatalf("line %d ok = %v, want %v: %#v", wantLines[i], r["ok"], wantOK[i], r)
323			}
324		}
325	
326		// Successful records keep input order and show the cross-midnight UTC dates.
327		if got := eventOf(t, results[0])[FieldTimestamp]; got != "2000-02-29T12:00:00Z" {
328			t.Fatalf("line 1 timestamp %v", got)
329		}
330		if got := eventOf(t, results[2])[FieldTimestamp]; got != "2026-04-15T12:00:00Z" {
331			t.Fatalf("line 4 timestamp %v", got)
332		}
333		event6 := eventOf(t, results[4])
334		if got := event6[FieldTimestamp]; got != "2000-02-29T00:30:00Z" || event6[FieldAction] != "e" {
335			t.Fatalf("line 7 must cross onto the leap day with its action intact: %#v", event6)
336		}
337		event9 := eventOf(t, results[6])
338		if got := event9[FieldTimestamp]; got != "2000-05-01T00:30:00Z" || event9[FieldAction] != "g" {
339			t.Fatalf("final line must cross from April 30 to May 1: %#v", event9)
340		}
341	
342		// Each date failure is error-only and names the timestamp calendar problem.
343		for _, idx := range []int{1, 3, 5} {
344			r := results[idx]
345			if _, exists := r["event"]; exists {
346				t.Fatalf("line %v failure must carry no event: %#v", r["line"], r)
347			}
348			msg, _ := r["error"].(string)
349			if !strings.Contains(msg, FieldTimestamp) || !strings.Contains(msg, "day out of range") {
350				t.Fatalf("line %v error must name %q's date problem, got %q", r["line"], FieldTimestamp, msg)
351			}
352		}
353	}
