137	// survive — neither is treated as a network or broadcast address — the
138	// immediate neighbors do not, and spelling the option with the pair's other
139	// address produces byte-identical output.
140	func TestNormalizeCLISourceCIDRSlash31KeepsBothAddresses(t *testing.T) {
